// ISO 4762 Socket head cap screw (screws). Generated by the standard parts library; threads are not modelled.
let TABLE = [
    [2.0, 3.8, 2.0, 1.5, 1.0],
    [2.5, 4.5, 2.5, 2.0, 1.1],
    [3.0, 5.5, 3.0, 2.5, 1.3],
    [4.0, 7.0, 4.0, 3.0, 2.0],
    [5.0, 8.5, 5.0, 4.0, 2.5],
    [6.0, 10.0, 6.0, 5.0, 3.0],
    [8.0, 13.0, 8.0, 6.0, 4.0],
    [10.0, 16.0, 10.0, 8.0, 5.0],
    [12.0, 18.0, 12.0, 10.0, 6.0],
    [16.0, 24.0, 16.0, 14.0, 8.0],
    [20.0, 30.0, 20.0, 17.0, 10.0]
];
let row = [];
for r in TABLE { if abs(r[0] - size) < 1e-6 { row = r; } }
if row.len() == 0 { throw "no size " + size + "; the sizes are M2, M2.5, M3, M4, M5, M6, M8, M10, M12, M16, M20"; }
if length <= 0.0 { throw "the length must be positive"; }

fn hex(s) {
    let r = s / sqrt(3.0);
    let p = [];
    for i in 0..6 { let a = (30.0 + 60.0 * i).to_radians(); p.push([r * cos(a), r * sin(a)]); }
    p
}
fn hexc(s, h, top, bottom) {
    let r0 = 0.475 * s;
    let big = 1.02 * s / sqrt(3.0);
    let dz = (big - r0) * 0.57735;
    let p = [[0.0, 0.0]];
    if bottom { p.push([r0, 0.0]); p.push([big, dz]); } else { p.push([big, 0.0]); }
    if top { p.push([big, h - dz]); p.push([r0, h]); } else { p.push([big, h]); }
    p.push([0.0, h]);
    prism(hex(s), h) & revolve(p, 360.0)
}
fn rp(x0, y0, x1, y1, h) { prism([[x0, y0], [x1, y0], [x1, y1], [x0, y1]], h) }

let d = size; let dk = row[1]; let k = row[2]; let s = row[3]; let t = row[4];
let c = 0.08 * d; let kc = 0.06 * dk;
let body = revolve([[0.0, -length], [d / 2 - c, -length], [d / 2, -length + c], [d / 2, 0.0], [dk / 2, 0.0], [dk / 2, k - kc], [dk / 2 - kc, k], [0.0, k]], 360.0);
body - prism(hex(s), t + 1.0).move(0.0, 0.0, k - t)

